                var inFVec = Vector.ConvertToSingle(inVec);
                var scaled = Vector.Divide(inFVec, ScaleVec);
                Vector.Store(scaled, &input[i]);
            }
            
            // compute l1

            for (int j = 0; j < L1_SIZE; j += step)
            {
                var bVec = Vector.Load(&b1p[j]);
                Vector.Store(bVec, &acc[j]);
            }

            for (int j = 0; j < L1_SIZE; j++)
            {
                for (int i = 0; i < INPUT_SIZE; i += step)
                {
                    var iVec = Vector.Load(&input[i]);
                    var wVec = Vector.Load(&w1p[j * INPUT_SIZE + i]);
                    var mult = Vector.Multiply(iVec, wVec);
                    acc[j] += Vector.Sum(mult);
                }
