            // activate l1
            // leaky relu

            for (int j = 0; j < L1_SIZE; j += step)
            {
                var aVec = Vector.Load(&acc[j]);
                var relu = Vector.Max(aVec, Vector<float>.Zero);
                var leaky = Vector.Min(aVec, Vector<float>.Zero);
                leaky = Vector.Multiply(leaky, Vector.Create(ReLUSlope));
                var sum = Vector.Add(relu, leaky);
                Vector.Store(sum, &acc[j]);
